        this.closeBtn = this.modal.querySelector('.modal-close');
        this.cancelBtn = this.modal.querySelector('#cancelBtn');
        this.confirmBtn = this.modal.querySelector('#confirmDeleteBtn');
        this.triggers = document.querySelectorAll('.trigger');

        this.activeImageCard = null;

        this.init();
    }

