        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && this.modal.classList.contains('open')) {
                this.close();
            }
        });
    }

    open(trigger) {
        // Store reference to the card that triggered the modal
        this.activeImageCard = trigger.closest('.image-card');

        // Open the modal
        this.modal.classList.add('open');
        document.body.style.overflow = 'hidden';

        // Focus the close button for accessibility
        this.confirmBtn.focus();
    }

    close() {
        // Close the modal
        this.modal.classList.remove('open');
        document.body.style.overflow = '';

        // Clear the reference
        this.activeImageCard = null;
    }

    handleDelete() {
        if (!this.activeImageCard) return;

        // Get image info for the notification
        const imageName = this.activeImageCard.querySelector('.image-info h3')?.textContent || 'Image';

        // Simulate deletion with visual feedback
        this.activeImageCard.style.opacity = '0';
        this.activeImageCard.style.transform = 'scale(0.95)';
        this.activeImageCard.style.transition = 'all 0.3s ease';

        // After animation, remove the card and close the modal
        setTimeout(() => {
            this.activeImageCard.remove();
            this.close();

            // Show success notification
            this.showNotification(`"${imageName}" has been deleted from your library`);
        }, 300);
    }

    showNotification(message) {
        // Create and show a success notification
        const notification = document.createElement('div');
        notification.className = 'notification notification-success';
        notification.textContent = message;

        document.body.appendChild(notification);

        // Trigger animation
        setTimeout(() => {
            notification.classList.add('show');
        }, 10);

        // Remove after 3 seconds
        setTimeout(() => {
            notification.classList.remove('show');
            setTimeout(() => {
                notification.remove();
            }, 300);
        }, 3000);
    }
}

// Initialize modal dialog when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    new ModalDialog('deleteModal');
});
